from rich.segment import Segment
from rich.cells import cell_len
import itertools
for t in ['早乙女リリエル (CV: 徳井青)','a早b乙c','💩💩x','ab💩']:
  for c in range(cell_len(t)+2):
    a,b=Segment(t).split_cells(c)
    assert cell_len(a.text)==min(c,cell_len(t)) and cell_len(a.text)+cell_len(b.text)==cell_len(t),(t,c,a,b)
print('ok')
